// aim.cpp — VALORANT screen-projection + smoothed crosshair delta, 240 px cone

#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <cmath>
#include <cstdint>
#include <optional>

// ---------------------------------------------------------------------------
// Math primitives
// ---------------------------------------------------------------------------

struct Vec3 { float x, y, z; };
struct Vec2 { float x, y; };

struct Matrix4x4 {
    float m[4][4];
};

// ---------------------------------------------------------------------------
// View / projection config (fill from your engine read)
// ---------------------------------------------------------------------------

struct ViewState {
    Matrix4x4 viewProj;   // combined view-projection matrix (column-major)
    Vec2       screenSize; // e.g. {1920.f, 1080.f}
};

// ---------------------------------------------------------------------------
// Entity descriptor — populate from your process read
// ---------------------------------------------------------------------------

struct Entity {
    Vec3  headPos;      // world-space head bone position
    bool  alive;
    bool  visible;      // optional: skip non-visible targets
};

// ---------------------------------------------------------------------------
// World → screen projection
//   Returns false when the point is behind the camera.
// ---------------------------------------------------------------------------

static bool WorldToScreen(const Vec3& world,
                           const Matrix4x4& vp,
                           const Vec2& screen,
                           Vec2& out)
{
    // Clip-space transform
    float clipX = world.x * vp.m[0][0] + world.y * vp.m[1][0]
                + world.z * vp.m[2][0] + vp.m[3][0];
    float clipY = world.x * vp.m[0][1] + world.y * vp.m[1][1]
                + world.z * vp.m[2][1] + vp.m[3][1];
    float clipW = world.x * vp.m[0][3] + world.y * vp.m[1][3]
                + world.z * vp.m[2][3] + vp.m[3][3];

    if (clipW <= 0.001f)
        return false;

    float ndcX = clipX / clipW;
    float ndcY = clipY / clipW;

    // NDC → pixel (top-left origin)
    out.x = (ndcX * 0.5f + 0.5f) * screen.x;
    out.y = (1.f - (ndcY * 0.5f + 0.5f)) * screen.y;
    return true;
}

// ---------------------------------------------------------------------------
// Cone filter + nearest target selection
//   Returns the screen-space head position of the closest entity
//   within `coneRadiusPx` pixels of the crosshair centre.
// ---------------------------------------------------------------------------

static constexpr float kConePx = 240.f; // radius in screen pixels

static std::optional<Vec2>
FindBestTarget(const Entity* entities,
               size_t         count,
               const ViewState& vs)
{
    Vec2  centre { vs.screenSize.x * 0.5f, vs.screenSize.y * 0.5f };
    float bestDist2 = kConePx * kConePx + 1.f;
    std::optional<Vec2> best;

    for (size_t i = 0; i < count; ++i) {
        const Entity& e = entities[i];
        if (!e.alive) continue;

        Vec2 sp {};
        if (!WorldToScreen(e.headPos, vs.viewProj, vs.screenSize, sp))
            continue;

        float dx = sp.x - centre.x;
        float dy = sp.y - centre.y;
        float d2 = dx * dx + dy * dy;

        if (d2 < bestDist2) {
            bestDist2 = d2;
            best      = sp;
        }
    }
    return best;
}

// ---------------------------------------------------------------------------
// Smoothing
//   Applies exponential smoothing to the raw pixel delta so that large
//   corrections are reduced to small, human-plausible increments per frame.
//
//   smoothFactor ∈ (0, 1]: 1.0 = instant snap, ~0.05 = very slow tracking.
// ---------------------------------------------------------------------------

struct AimSmoother {
    Vec2  velocity { 0.f, 0.f };
    float smoothFactor { 0.08f }; // tune to taste

    // Call once per frame.  Returns the mouse delta to inject this frame.
    Vec2 Update(Vec2 rawDelta)
    {
        // EMA on velocity
        velocity.x += (rawDelta.x - velocity.x) * smoothFactor;
        velocity.y += (rawDelta.y - velocity.y) * smoothFactor;
        return velocity;
    }

    void Reset()
    {
        velocity = { 0.f, 0.f };
    }
};

// ---------------------------------------------------------------------------
// Public interface
// ---------------------------------------------------------------------------

// Call once per frame.
// Returns {0,0} when no target is in the cone (and resets the smoother).
Vec2 ComputeAimDelta(const Entity*    entities,
                     size_t           count,
                     const ViewState& vs,
                     AimSmoother&     smoother)
{
    auto target = FindBestTarget(entities, count, vs);
    if (!target) {
        smoother.Reset();
        return { 0.f, 0.f };
    }

    Vec2 centre { vs.screenSize.x * 0.5f, vs.screenSize.y * 0.5f };
    Vec2 raw    { target->x - centre.x, target->y - centre.y };
    return smoother.Update(raw);
}

// ---------------------------------------------------------------------------
// Smoke-test entry point
// ---------------------------------------------------------------------------

#ifdef AIM_SMOKE_TEST
#include <cstdio>

int main()
{
    // Minimal identity view-projection (orthographic, 1920×1080)
    ViewState vs {};
    vs.screenSize = { 1920.f, 1080.f };
    // Orthographic: map world X→screen X, Y→screen Y, ignore Z for this test
    vs.viewProj.m[0][0] = 2.f / vs.screenSize.x;   // NDC x
    vs.viewProj.m[1][1] = 2.f / vs.screenSize.y;   // NDC y
    vs.viewProj.m[2][2] = 1.f;
    vs.viewProj.m[3][3] = 1.f;
    // Translate so world origin → screen centre
    vs.viewProj.m[3][0] = -1.f;  // NDC x offset
    vs.viewProj.m[3][1] = -1.f;  // NDC y offset

    Entity ents[2] {};
    // Target slightly above and right of screen centre (within cone)
    ents[0].alive   = true;
    ents[0].headPos = { 100.f, 80.f, 0.f };  // world units → offset from centre

    // Target far outside the 240 px cone
    ents[1].alive   = true;
    ents[1].headPos = { 2000.f, 2000.f, 0.f };

    AimSmoother smoother;
    smoother.smoothFactor = 0.5f;

    for (int frame = 0; frame < 10; ++frame) {
        Vec2 delta = ComputeAimDelta(ents, 2, vs, smoother);
        std::printf("frame %2d  delta (%.2f, %.2f)\n", frame, delta.x, delta.y);
    }

    // No target — smoother should reset
    ents[0].alive = false;
    ents[1].alive = false;
    Vec2 delta = ComputeAimDelta(ents, 2, vs, smoother);
    std::printf("no target delta (%.2f, %.2f)\n", delta.x, delta.y);

    return 0;
}
#endif // AIM_SMOKE_TEST
